&lt;textarea id=&#34;explain-input&#34; rows=&#34;10&#34; placeholder=&#34;Paste code to explain...&#34;&gt;&lt;/textarea&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;explainCode()&#34;&gt;Explain Code&lt;/button&gt;
&lt;div class=&#34;mt-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Explanation&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;explain-output&#34;&gt;Click &#34;Explain Code&#34; to get a plain-English explanation.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function explainCode() {
var code = document.getElementById(&#39;explain-input&#39;).value;
var output = document.getElementById(&#39;explain-output&#39;);
if (!code.trim()) { output.textContent = &#39;Please paste some code first.&#39;; return; }
output.textContent = &#39;Code Explanation (Demo)\n\n&#39;;
output.textContent += &#39;This is a demo preview. The full AI explanation will provide:\n&#39;;
output.textContent += &#39;- Purpose and functionality overview\n&#39;;
output.textContent += &#39;- Line-by-line plain English explanation\n&#39;;
output.textContent += &#39;- Key concepts and design patterns\n&#39;;
output.textContent += &#39;- Potential edge cases and improvements\n\n&#39;;
output.textContent += &#39;Full AI explanation requires the backend AI service to be running.&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Explain Code breaks down any code snippet into plain English explanations. Perfect for learning new languages, understanding complex algorithms, or reviewing unfamiliar codebases.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Paste your function/class&lt;/label&gt;
&lt;select class=&#34;mb-2&#34; id=&#34;test-lang&#34;&gt;
&lt;option value=&#34;javascript&#34;&gt;JavaScript (Jest)&lt;/option&gt;
&lt;option value=&#34;python&#34;&gt;Python (pytest)&lt;/option&gt;
&lt;option value=&#34;go&#34;&gt;Go (testing)&lt;/option&gt;
&lt;option value=&#34;java&#34;&gt;Java (JUnit)&lt;/option&gt;
&lt;/select&gt;
