&lt;div class=&#34;mt-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Results&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;grammar-output&#34;&gt;Click &#34;Check Grammar&#34; to analyze your text.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function checkGrammar() {
var text = document.getElementById(&#39;grammar-input&#39;).value;
var output = document.getElementById(&#39;grammar-output&#39;);
if (!text.trim()) { output.textContent = &#39;Please enter some text.&#39;; return; }
var wordCount = text.split(/\s+/).length;
var sentenceCount = text.split(/[.!?]+/).filter(function(s) { return s.trim().length &gt; 0; }).length;
var avgWordsPerSentence = sentenceCount &gt; 0 ? (wordCount / sentenceCount).toFixed(1) : 0;
output.textContent = &#39;Basic Grammar Check (Demo)\n\n&#39;;
output.textContent += &#39;Word count: &#39; + wordCount + &#39;\n&#39;;
output.textContent += &#39;Sentence count: &#39; + sentenceCount + &#39;\n&#39;;
output.textContent += &#39;Avg words/sentence: &#39; + avgWordsPerSentence + &#39;\n\n&#39;;
output.textContent += &#39;This is a demo preview. The full AI grammar check will detect:\n&#39;;
output.textContent += &#39;- Spelling errors\n&#39;;
output.textContent += &#39;- Grammar mistakes\n&#39;;
output.textContent += &#39;- Punctuation issues\n&#39;;
output.textContent += &#39;- Style and tone suggestions\n&#39;;
output.textContent += &#39;- Readability score\n\n&#39;;
output.textContent += &#39;Full grammar checking requires the backend AI service.&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Grammar Checker analyzes your text for grammar errors, spelling mistakes, punctuation issues, and style improvements. Write with confidence.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper text-center py-5&#34;&gt;
&lt;div class=&#34;bi bi-image&#34; style=&#34;font-size: 3rem; color: var(--primary);&#34;&gt;&lt;/div&gt;
&lt;h4 class=&#34;mt-3&#34;&gt;Compress Image&lt;/h4&gt;
&lt;p class=&#34;text-muted&#34;&gt;Upload an image to reduce its file size.&lt;/p&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;input type=&#34;file&#34; accept=&#34;image/*&#34; id=&#34;image-file&#34; class=&#34;form-control&#34; style=&#34;max-width: 400px; margin: 0 auto;&#34;&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label&#34;&gt;Quality: &lt;span id=&#34;quality-label&#34;&gt;80&lt;/span&gt;%&lt;/label&gt;
&lt;input type=&#34;range&#34; id=&#34;quality-range&#34; min=&#34;10&#34; max=&#34;100&#34; value=&#34;80&#34; class=&#34;form-range&#34; style=&#34;max-width: 300px; margin: 0 auto;&#34;&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;compressImage()&#34;&gt;Compress&lt;/button&gt;
&lt;div class=&#34;mt-3 row&#34;&gt;
&lt;div class=&#34;col-md-6&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Original&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;original-info&#34;&gt;No image selected.&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&#34;col-md-6&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Compressed&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;compressed-info&#34;&gt;Waiting for compression.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
document.getElementById(&#39;quality-range&#39;).addEventListener(&#39;input&#39;, function() {
document.getElementById(&#39;quality-label&#39;).textContent = this.value;
});
function compressImage() {
var file = document.getElementById(&#39;image-file&#39;).files[0];
var quality = document.getElementById(&#39;quality-range&#39;).value / 100;
var origInfo = document.getElementById(&#39;original-info&#39;);
var compInfo = document.getElementById(&#39;compressed-info&#39;);
if (!file) { origInfo.textContent = &#39;Please select an image file.&#39;; return; }
origInfo.textContent = &#39;Name: &#39; + file.name + &#39;\nSize: &#39; + (file.size / 1024).toFixed(1) + &#39; KB\nType: &#39; + file.type;
var reader = new FileReader();
reader.onload = function(e) {
var img = new Image();
img.onload = function() {
var canvas = document.createElement(&#39;canvas&#39;);
canvas.width = img.width;
canvas.height = img.height;
var ctx = canvas.getContext(&#39;2d&#39;);
ctx.drawImage(img, 0, 0);
var dataUrl = canvas.toDataURL(file.type, quality);
var base64 = dataUrl.split(&#39;,&#39;)[1];
var size = Math.round((base64.length * 3) / 4);
compInfo.textContent = &#39;Dimensions: &#39; + img.width + &#39;x&#39; + img.height + &#39;\nNew size: &#39; + (size / 1024).toFixed(1) + &#39; KB\nReduction: &#39; + Math.round((1 - size / file.size) * 100) + &#39;%\n\nRight-click to save the compressed image.&#39;;
};
img.src = e.target.result;
};
reader.readAsDataURL(file);
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Image Compressor reduces your image file size while maintaining visual quality. Perfect for web optimization, email attachments, and saving storage space.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Upload image to resize&lt;/label&gt;
&lt;input type=&#34;file&#34; id=&#34;resize-input&#34; accept=&#34;image/*&#34; class=&#34;form-control mb-2&#34; onchange=&#34;loadResizeImage()&#34;&gt;
&lt;/div&gt;
&lt;div class=&#34;row mb-3&#34;&gt;
&lt;div class=&#34;col-6&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Width (px)&lt;/label&gt;
&lt;input type=&#34;number&#34; id=&#34;resize-width&#34; class=&#34;form-control&#34; placeholder=&#34;800&#34; min=&#34;1&#34;&gt;
&lt;/div&gt;
&lt;div class=&#34;col-6&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Height (px)&lt;/label&gt;
&lt;input type=&#34;number&#34; id=&#34;resize-height&#34; class=&#34;form-control&#34; placeholder=&#34;600&#34; min=&#34;1&#34;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&#34;form-check mb-3&#34;&gt;
&lt;input type=&#34;checkbox&#34; id=&#34;resize-aspect&#34; class=&#34;form-check-input&#34; checked&gt;
&lt;label class=&#34;form-check-label&#34; for=&#34;resize-aspect&#34;&gt;Maintain aspect ratio&lt;/label&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary mb-3&#34; onclick=&#34;resizeImage()&#34;&gt;Resize &amp; Download&lt;/button&gt;
&lt;div&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Preview&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;resize-output&#34;&gt;Upload an image and set dimensions to resize.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
var resizeOriginalWidth = 0;
var resizeOriginalHeight = 0;
function loadResizeImage() {
var file = document.getElementById(&#39;resize-input&#39;).files[0];
if (!file) return;
var img = new Image();
img.onload = function() {
resizeOriginalWidth = img.width;
resizeOriginalHeight = img.height;
document.getElementById(&#39;resize-width&#39;).value = img.width;
document.getElementById(&#39;resize-height&#39;).value = img.height;
document.getElementById(&#39;resize-output&#39;).textContent = &#39;Image loaded: &#39; + img.width + &#39;x&#39; + img.height;
};
img.src = URL.createObjectURL(file);
}
function resizeImage() {
var file = document.getElementById(&#39;resize-input&#39;).files[0];
var w = parseInt(document.getElementById(&#39;resize-width&#39;).value);
var h = parseInt(document.getElementById(&#39;resize-height&#39;).value);
var maintain = document.getElementById(&#39;resize-aspect&#39;).checked;
var output = document.getElementById(&#39;resize-output&#39;);
if (!file) { output.textContent = &#39;Please upload an image first.&#39;; return; }
if (!w || !h) { output.textContent = &#39;Please enter valid dimensions.&#39;; return; }
if (maintain &amp;&amp; resizeOriginalWidth &gt; 0) {
var ratio = resizeOriginalWidth / resizeOriginalHeight;
h = Math.round(w / ratio);
document.getElementById(&#39;resize-height&#39;).value = h;
}
var img = new Image();
img.onload = function() {
var canvas = document.createElement(&#39;canvas&#39;);
canvas.width = w;
canvas.height = h;
var ctx = canvas.getContext(&#39;2d&#39;);
ctx.drawImage(img, 0, 0, w, h);
var link = document.createElement(&#39;a&#39;);
link.download = &#39;resized-&#39; + w + &#39;x&#39; + h + &#39;.&#39; + file.name.split(&#39;.&#39;).pop();
link.href = canvas.toDataURL(&#39;image/png&#39;);
link.click();
output.textContent = &#39;Image resized to &#39; + w + &#39;x&#39; + h + &#39; and downloaded.&#39;;
};
img.src = URL.createObjectURL(file);
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Image Resizer lets you resize images to any width and height. Maintain aspect ratio, choose output format, and download your resized image instantly.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Paste job description&lt;/label&gt;
&lt;textarea id=&#34;jd-input&#34; rows=&#34;12&#34; placeholder=&#34;Paste the full job description here...&#34;&gt;&lt;/textarea&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;analyzeJD()&#34;&gt;Analyze&lt;/button&gt;
&lt;div class=&#34;mt-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Analysis&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;jd-output&#34;&gt;Click &#34;Analyze&#34; to extract key information from the job description.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function analyzeJD() {
var text = document.getElementById(&#39;jd-input&#39;).value;
var output = document.getElementById(&#39;jd-output&#39;);
if (!text.trim()) { output.textContent = &#39;Please paste a job description.&#39;; return; }
