var sentences = text.split(/[.!?]+/).filter(function(s) { return s.trim().length &gt; 0; });
output.textContent = &#39;Job Description Analysis (Demo)\n\n&#39;;
output.textContent += &#39;Word count: &#39; + wordCount + &#39;\n&#39;;
output.textContent += &#39;Estimated reading time: &#39; + Math.ceil(wordCount / 200) + &#39; min\n\n&#39;;
output.textContent += &#39;This is a demo preview. The full analysis will extract:\n&#39;;
output.textContent += &#39;- Required skills and qualifications\n&#39;;
output.textContent += &#39;- Preferred skills and nice-to-haves\n&#39;;
output.textContent += &#39;- Years of experience required\n&#39;;
output.textContent += &#39;- Education requirements\n&#39;;
output.textContent += &#39;- Key responsibilities\n&#39;;
output.textContent += &#39;- Company culture indicators\n&#39;;
output.textContent += &#39;- Salary range (if mentioned)\n\n&#39;;
output.textContent += &#39;Full analysis requires the backend AI service.&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Job Description Analyzer extracts key information from any job posting — required skills, experience levels, responsibilities, and company culture indicators. Tailor your application with precision.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;row mb-3&#34;&gt;
&lt;div class=&#34;col-md-6&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Left JSON&lt;/label&gt;
&lt;textarea id=&#34;diff-left&#34; rows=&#34;8&#34; placeholder=&#39;{&#34;original&#34;:&#34;value&#34;}&#39;&gt;&lt;/textarea&gt;
&lt;/div&gt;
&lt;div class=&#34;col-md-6&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Right JSON&lt;/label&gt;
&lt;textarea id=&#34;diff-right&#34; rows=&#34;8&#34; placeholder=&#39;{&#34;modified&#34;:&#34;value&#34;}&#39;&gt;&lt;/textarea&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary mb-3&#34; onclick=&#34;diffJSON()&#34;&gt;Compare&lt;/button&gt;
&lt;div&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Differences&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;diff-output&#34;&gt;Click &#34;Compare&#34; to find differences between two JSON objects.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function diffJSON() {
var left = document.getElementById(&#39;diff-left&#39;).value;
var right = document.getElementById(&#39;diff-right&#39;).value;
var output = document.getElementById(&#39;diff-output&#39;);
if (!left.trim() || !right.trim()) { output.textContent = &#39;Please enter both JSON values.&#39;; return; }
try {
var l = JSON.parse(left);
var r = JSON.parse(right);
var diffs = [];
function compare(a, b, path) {
if (typeof a !== typeof b) { diffs.push(&#39;TYPE MISMATCH at &#39; + path + &#39;: &#39; + typeof a + &#39; vs &#39; + typeof b); return; }
if (a === null &amp;&amp; b === null) return;
if (typeof a !== &#39;object&#39;) { if (a !== b) diffs.push(&#39;CHANGED at &#39; + path + &#39;: &#34;&#39; + a + &#39;&#34; → &#34;&#39; + b + &#39;&#34;&#39;); return; }
if (Array.isArray(a) !== Array.isArray(b)) { diffs.push(&#39;TYPE MISMATCH at &#39; + path); return; }
var allKeys = new Set([].concat(Object.keys(a), Object.keys(b)));
allKeys.forEach(function(k) {
var p = path ? path + &#39;.&#39; + k : k;
if (!(k in a)) diffs.push(&#39;ADDED at &#39; + p + &#39;: &#39; + JSON.stringify(b[k]));
else if (!(k in b)) diffs.push(&#39;REMOVED at &#39; + p + &#39;: &#39; + JSON.stringify(a[k]));
else compare(a[k], b[k], p);
});
}
compare(l, r, &#39;&#39;);
if (diffs.length === 0) output.textContent = &#39;✓ No differences found. JSON objects are identical.&#39;;
else output.textContent = diffs.join(&#39;\n&#39;);
} catch(e) { output.textContent = &#39;Error: &#39; + e.message; }
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;JSON Diff compares two JSON objects side-by-side and highlights differences. Perfect for debugging API responses, tracking configuration changes, and reviewing data migrations.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Enter JSON&lt;/label&gt;
&lt;textarea id=&#34;json-input&#34; rows=&#34;8&#34; placeholder=&#39;Paste your JSON here... e.g. {&#34;name&#34;:&#34;John&#34;,&#34;age&#34;:30}&#39;&gt;&lt;/textarea&gt;
&lt;/div&gt;
&lt;div class=&#34;d-flex gap-2 mb-3 flex-wrap&#34;&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;formatJSON()&#34;&gt;Format&lt;/button&gt;
&lt;button class=&#34;btn btn-outline-secondary&#34; onclick=&#34;minifyJSON()&#34;&gt;Minify&lt;/button&gt;
&lt;button class=&#34;btn btn-outline-secondary&#34; onclick=&#34;validateJSON()&#34;&gt;Validate&lt;/button&gt;
&lt;button class=&#34;btn btn-outline-secondary&#34; onclick=&#34;clearJSON()&#34;&gt;Clear&lt;/button&gt;
&lt;/div&gt;
&lt;div class=&#34;position-relative&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Output&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;json-output&#34;&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function formatJSON() {
var input = document.getElementById(&#39;json-input&#39;);
var output = document.getElementById(&#39;json-output&#39;);
try { output.textContent = JSON.stringify(JSON.parse(input.value), null, 2); }
catch(e) { output.textContent = &#39;Error: &#39; + e.message; }
}
function minifyJSON() {
var input = document.getElementById(&#39;json-input&#39;);
var output = document.getElementById(&#39;json-output&#39;);
try { output.textContent = JSON.stringify(JSON.parse(input.value)); }
catch(e) { output.textContent = &#39;Error: &#39; + e.message; }
}
function validateJSON() {
var input = document.getElementById(&#39;json-input&#39;);
var output = document.getElementById(&#39;json-output&#39;);
try { JSON.parse(input.value); output.textContent = &#39;✓ Valid JSON&#39;; }
catch(e) { output.textContent = &#39;✗ Invalid JSON: &#39; + e.message; }
}
function clearJSON() {
document.getElementById(&#39;json-input&#39;).value = &#39;&#39;;
document.getElementById(&#39;json-output&#39;).textContent = &#39;&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;JSON Formatter is a free online tool that helps you beautify, minify, and validate JSON data. Whether you&amp;rsquo;re debugging an API response or formatting configuration files, this tool makes JSON readable in seconds.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper text-center py-5&#34;&gt;
&lt;div class=&#34;bi bi-file-earmark-pdf&#34; style=&#34;font-size: 3rem; color: var(--primary);&#34;&gt;&lt;/div&gt;
&lt;h4 class=&#34;mt-3&#34;&gt;Merge PDF Files&lt;/h4&gt;
&lt;p class=&#34;text-muted&#34;&gt;Select multiple PDF files to combine them into one document.&lt;/p&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;input type=&#34;file&#34; accept=&#34;.pdf&#34; multiple id=&#34;pdf-files&#34; class=&#34;form-control&#34; style=&#34;max-width: 400px; margin: 0 auto;&#34;&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;mergePDFs()&#34; disabled id=&#34;merge-btn&#34;&gt;Merge PDFs&lt;/button&gt;
&lt;div class=&#34;mt-3&#34;&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;merge-output&#34;&gt;Select PDF files to merge.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
document.getElementById(&#39;pdf-files&#39;).addEventListener(&#39;change&#39;, function() {
document.getElementById(&#39;merge-btn&#39;).disabled = this.files.length &lt; 2;
document.getElementById(&#39;merge-output&#39;).textContent = this.files.length + &#39; file(s) selected.&#39;;
});
function mergePDFs() {
var files = document.getElementById(&#39;pdf-files&#39;).files;
var output = document.getElementById(&#39;merge-output&#39;);
if (files.length &lt; 2) { output.textContent = &#39;Please select at least 2 PDF files.&#39;; return; }
var names = [];
for (var i = 0; i &lt; files.length; i++) names.push(files[i].name);
output.textContent = &#39;Selected files:\n&#39; + names.join(&#39;\n&#39;) + &#39;\n\nPDF merge requires PDF.js or a backend service. This is a UI placeholder.&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Merge PDF lets you combine multiple PDF files into a single document quickly and securely. All processing happens in your browser — your files never leave your device.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Page title&lt;/label&gt;
&lt;input type=&#34;text&#34; id=&#34;meta-title&#34; class=&#34;form-control&#34; placeholder=&#34;Your Page Title | Site Name&#34;&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Meta description&lt;/label&gt;
&lt;textarea id=&#34;meta-desc&#34; class=&#34;form-control&#34; rows=&#34;3&#34; placeholder=&#34;Brief description of your page (150-160 characters recommended)&#34;&gt;&lt;/textarea&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Page URL&lt;/label&gt;
&lt;input type=&#34;url&#34; id=&#34;meta-url&#34; class=&#34;form-control&#34; placeholder=&#34;https://example.com/page&#34;&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Site name&lt;/label&gt;
&lt;input type=&#34;text&#34; id=&#34;meta-site&#34; class=&#34;form-control&#34; placeholder=&#34;Your Site Name&#34;&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;generateMeta()&#34;&gt;Generate Meta Tags&lt;/button&gt;
&lt;div class=&#34;mt-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;HTML Meta Tags&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;meta-output&#34;&gt;Fill in the fields and click &#34;Generate Meta Tags&#34;.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function generateMeta() {
var title = document.getElementById(&#39;meta-title&#39;).value.trim();
var desc = document.getElementById(&#39;meta-desc&#39;).value.trim();
var url = document.getElementById(&#39;meta-url&#39;).value.trim();
var site = document.getElementById(&#39;meta-site&#39;).value.trim();
var output = document.getElementById(&#39;meta-output&#39;);
if (!title || !desc) { output.textContent = &#39;Please enter at least the title and description.&#39;; return; }
var html = &#39;\x3C!-- Primary Meta Tags --&gt;\n&#39;;
html += &#39;&lt;title&gt;&#39; + title + &#39;&lt;/title&gt;\n&#39;;
html += &#39;&lt;meta name=&#34;title&#34; content=&#34;&#39; + title + &#39;&#34;&gt;\n&#39;;
html += &#39;&lt;meta name=&#34;description&#34; content=&#34;&#39; + desc + &#39;&#34;&gt;\n\n&#39;;
html += &#39;\x3C!-- Open Graph / Facebook --&gt;\n&#39;;
html += &#39;&lt;meta property=&#34;og:type&#34; content=&#34;website&#34;&gt;\n&#39;;
html += &#39;&lt;meta property=&#34;og:url&#34; content=&#34;&#39; + (url || &#39;https://example.com&#39;) + &#39;&#34;&gt;\n&#39;;
html += &#39;&lt;meta property=&#34;og:title&#34; content=&#34;&#39; + title + &#39;&#34;&gt;\n&#39;;
html += &#39;&lt;meta property=&#34;og:description&#34; content=&#34;&#39; + desc + &#39;&#34;&gt;\n&#39;;
if (site) html += &#39;&lt;meta property=&#34;og:site_name&#34; content=&#34;&#39; + site + &#39;&#34;&gt;\n\n&#39;;
else html += &#39;\n&#39;;
html += &#39;\x3C!-- Twitter --&gt;\n&#39;;
html += &#39;&lt;meta property=&#34;twitter:card&#34; content=&#34;summary_large_image&#34;&gt;\n&#39;;
html += &#39;&lt;meta property=&#34;twitter:url&#34; content=&#34;&#39; + (url || &#39;https://example.com&#39;) + &#39;&#34;&gt;\n&#39;;
html += &#39;&lt;meta property=&#34;twitter:title&#34; content=&#34;&#39; + title + &#39;&#34;&gt;\n&#39;;
html += &#39;&lt;meta property=&#34;twitter:description&#34; content=&#34;&#39; + desc + &#39;&#34;&gt;\n&#39;;
output.textContent = html;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Meta Tag Generator creates SEO-optimized meta tags for your web pages. Generate title tags, meta descriptions, Open Graph tags, and Twitter cards.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;row mb-3&#34;&gt;
&lt;div class=&#34;col-md-4&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Length&lt;/label&gt;
&lt;input type=&#34;number&#34; id=&#34;pw-length&#34; class=&#34;form-control&#34; value=&#34;16&#34; min=&#34;8&#34; max=&#34;64&#34;&gt;
&lt;/div&gt;
&lt;div class=&#34;col-md-8&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Options&lt;/label&gt;
&lt;div class=&#34;d-flex gap-3 flex-wrap&#34;&gt;
&lt;div class=&#34;form-check&#34;&gt;&lt;input type=&#34;checkbox&#34; id=&#34;pw-upper&#34; class=&#34;form-check-input&#34; checked&gt;&lt;label class=&#34;form-check-label&#34; for=&#34;pw-upper&#34;&gt;A-Z&lt;/label&gt;&lt;/div&gt;
&lt;div class=&#34;form-check&#34;&gt;&lt;input type=&#34;checkbox&#34; id=&#34;pw-lower&#34; class=&#34;form-check-input&#34; checked&gt;&lt;label class=&#34;form-check-label&#34; for=&#34;pw-lower&#34;&gt;a-z&lt;/label&gt;&lt;/div&gt;
&lt;div class=&#34;form-check&#34;&gt;&lt;input type=&#34;checkbox&#34; id=&#34;pw-digits&#34; class=&#34;form-check-input&#34; checked&gt;&lt;label class=&#34;form-check-label&#34; for=&#34;pw-digits&#34;&gt;0-9&lt;/label&gt;&lt;/div&gt;
&lt;div class=&#34;form-check&#34;&gt;&lt;input type=&#34;checkbox&#34; id=&#34;pw-symbols&#34; class=&#34;form-check-input&#34;&gt;&lt;label class=&#34;form-check-label&#34; for=&#34;pw-symbols&#34;&gt;!@#$%&lt;/label&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Number of passwords&lt;/label&gt;
&lt;input type=&#34;number&#34; id=&#34;pw-count&#34; class=&#34;form-control&#34; value=&#34;1&#34; min=&#34;1&#34; max=&#34;50&#34; style=&#34;max-width:100px&#34;&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary mb-3&#34; onclick=&#34;generatePasswords()&#34;&gt;Generate&lt;/button&gt;
&lt;div&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Generated Passwords&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;pw-output&#34;&gt;Click &#34;Generate&#34; to create secure passwords.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function generatePasswords() {
var len = parseInt(document.getElementById(&#39;pw-length&#39;).value) || 16;
var count = parseInt(document.getElementById(&#39;pw-count&#39;).value) || 1;
var useUpper = document.getElementById(&#39;pw-upper&#39;).checked;
var useLower = document.getElementById(&#39;pw-lower&#39;).checked;
var useDigits = document.getElementById(&#39;pw-digits&#39;).checked;
var useSymbols = document.getElementById(&#39;pw-symbols&#39;).checked;
var output = document.getElementById(&#39;pw-output&#39;);
if (!useUpper &amp;&amp; !useLower &amp;&amp; !useDigits &amp;&amp; !useSymbols) { output.textContent = &#39;Select at least one character type.&#39;; return; }
var chars = &#39;&#39;;
if (useUpper) chars += &#39;ABCDEFGHIJKLMNOPQRSTUVWXYZ&#39;;
if (useLower) chars += &#39;abcdefghijklmnopqrstuvwxyz&#39;;
if (useDigits) chars += &#39;0123456789&#39;;
if (useSymbols) chars += &#39;!@#$%^&amp;*()_+-=[]{}|;:,.&lt;&gt;?&#39;;
var result = &#39;&#39;;
for (var p = 0; p &lt; count; p++) {
var pw = &#39;&#39;;
for (var i = 0; i &lt; len; i++) {
pw += chars.charAt(Math.floor(Math.random() * chars.length));
}
result += pw + &#39;\n&#39;;
}
output.textContent = result.trim();
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Password Generator creates strong, secure passwords based on your requirements. Customize length, character types, and generate multiple passwords at once.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Upload PDF to protect&lt;/label&gt;
&lt;input type=&#34;file&#34; id=&#34;pdf-protect-input&#34; accept=&#34;.pdf&#34; class=&#34;form-control mb-2&#34;&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Password&lt;/label&gt;
&lt;input type=&#34;password&#34; id=&#34;pdf-protect-password&#34; class=&#34;form-control&#34; placeholder=&#34;Enter password to protect PDF&#34;&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;protectPDF()&#34;&gt;Protect PDF&lt;/button&gt;
&lt;div class=&#34;mt-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Result&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;pdf-protect-output&#34;&gt;Upload a PDF and set a password. Note: This requires server-side processing.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function protectPDF() {
var file = document.getElementById(&#39;pdf-protect-input&#39;).files[0];
var password = document.getElementById(&#39;pdf-protect-password&#39;).value;
var output = document.getElementById(&#39;pdf-protect-output&#39;);
if (!file) { output.textContent = &#39;Please upload a PDF file.&#39;; return; }
if (!password) { output.textContent = &#39;Please enter a password.&#39;; return; }
output.textContent = &#39;PDF Protector (Demo)\n\n&#39;;
output.textContent += &#39;File: &#39; + file.name + &#39; (&#39; + (file.size / 1024).toFixed(1) + &#39; KB)\n&#39;;
output.textContent += &#39;Password set: Yes\n\n&#39;;
output.textContent += &#39;This tool requires server-side PDF processing.\n&#39;;
output.textContent += &#39;Full PDF protection will be available when the backend is running.\n\n&#39;;
output.textContent += &#39;Planned features:\n&#39;;
output.textContent += &#39;- Password-protect PDF files\n&#39;;
output.textContent += &#39;- Restrict printing and editing\n&#39;;
output.textContent += &#39;- Remove password protection&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Protect PDF lets you add password protection to your PDF documents. Prevent unauthorized access and control who can view or edit your files.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Content Type&lt;/label&gt;
&lt;select id=&#34;qr-type&#34; onchange=&#34;toggleQRType()&#34;&gt;
&lt;option value=&#34;url&#34;&gt;URL&lt;/option&gt;
&lt;option value=&#34;text&#34;&gt;Plain Text&lt;/option&gt;
&lt;option value=&#34;email&#34;&gt;Email&lt;/option&gt;
&lt;option value=&#34;phone&#34;&gt;Phone&lt;/option&gt;
&lt;option value=&#34;wifi&#34;&gt;WiFi&lt;/option&gt;
&lt;/select&gt;
&lt;/div&gt;
&lt;div id=&#34;qr-fields&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label&#34;&gt;Value&lt;/label&gt;
&lt;input type=&#34;text&#34; id=&#34;qr-value&#34; placeholder=&#34;https://example.com&#34;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label&#34;&gt;Size&lt;/label&gt;
&lt;select id=&#34;qr-size&#34;&gt;
&lt;option value=&#34;128&#34;&gt;Small (128px)&lt;/option&gt;
&lt;option value=&#34;256&#34; selected&gt;Medium (256px)&lt;/option&gt;
&lt;option value=&#34;512&#34;&gt;Large (512px)&lt;/option&gt;
&lt;/select&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;generateQR()&#34;&gt;Generate QR Code&lt;/button&gt;
&lt;div class=&#34;mt-3 text-center&#34;&gt;
&lt;div id=&#34;qr-output&#34; class=&#34;p-3 d-inline-block rounded&#34; style=&#34;background: var(--color-neutral-900);&#34;&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function toggleQRType() {
var type = document.getElementById(&#39;qr-type&#39;).value;
var label = document.getElementById(&#39;qr-fields&#39;).querySelector(&#39;label&#39;);
var input = document.getElementById(&#39;qr-value&#39;);
var placeholders = { url: &#39;https://example.com&#39;, text: &#39;Hello World&#39;, email: &#39;name@example.com&#39;, phone: &#39;+1234567890&#39;, wifi: &#39;NetworkName&#39; };
input.placeholder = placeholders[type] || &#39;Enter value&#39;;
}
function generateQR() {
var type = document.getElementById(&#39;qr-type&#39;).value;
var value = document.getElementById(&#39;qr-value&#39;).value.trim();
var size = document.getElementById(&#39;qr-size&#39;).value;
var output = document.getElementById(&#39;qr-output&#39;);
if (!value) { output.innerHTML = &#39;&lt;p class=&#34;text-muted&#34;&gt;Please enter a value.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Scan QR code&lt;/label&gt;
&lt;div class=&#34;d-flex gap-2 flex-wrap&#34;&gt;
&lt;input type=&#34;file&#34; id=&#34;qr-scanner-input&#34; accept=&#34;image/*&#34; class=&#34;form-control&#34; onchange=&#34;scanQRFile()&#34;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;startQRScanner()&#34;&gt;Use Camera&lt;/button&gt;
&lt;button class=&#34;btn btn-outline-secondary&#34; onclick=&#34;stopQRScanner()&#34;&gt;Stop Camera&lt;/button&gt;
&lt;/div&gt;
&lt;video id=&#34;qr-video&#34; style=&#34;max-width:100%;max-height:300px;display:none;border-radius:var(--radius-sm);border:1px solid var(--border);&#34;&gt;&lt;/video&gt;
&lt;div class=&#34;mt-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Decoded Content&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;qr-scan-output&#34;&gt;Upload a QR code image or use your camera to scan.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
var qrStream = null;
function scanQRFile() {
var file = document.getElementById(&#39;qr-scanner-input&#39;).files[0];
var output = document.getElementById(&#39;qr-scan-output&#39;);
if (!file) return;
output.textContent = &#39;QR code image loaded: &#39; + file.name + &#39;\n\nDecoding requires jsQR library.\n\nFor full QR scanning, the jsQR library will be loaded from CDN.&#39;;
}
function startQRScanner() {
var video = document.getElementById(&#39;qr-video&#39;);
var output = document.getElementById(&#39;qr-scan-output&#39;);
if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
output.textContent = &#39;Camera not supported in this browser. Use the file upload method instead.&#39;; return;
}
navigator.mediaDevices.getUserMedia({ video: { facingMode: &#39;environment&#39; } }).then(function(s) {
qrStream = s;
video.srcObject = s;
video.style.display = &#39;block&#39;;
video.play();
output.textContent = &#39;Camera active. Point at a QR code.\n\nFull real-time scanning requires jsQR library.&#39;;
}).catch(function(e) {
output.textContent = &#39;Camera access denied: &#39; + e.message;
});
}
function stopQRScanner() {
var video = document.getElementById(&#39;qr-video&#39;);
if (qrStream) { qrStream.getTracks().forEach(function(t) { t.stop(); }); qrStream = null; }
video.style.display = &#39;none&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;QR Scanner lets you scan QR codes using your device camera or by uploading a QR code image. Decode URLs, text, contact info, and more from any QR code.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Paste your resume text&lt;/label&gt;
&lt;textarea id=&#34;resume-opt-input&#34; rows=&#34;12&#34; placeholder=&#34;Paste your full resume text here...&#34;&gt;&lt;/textarea&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;optimizeResume()&#34;&gt;Optimize Resume&lt;/button&gt;
&lt;div class=&#34;mt-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Optimization Suggestions&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;resume-opt-output&#34;&gt;Click &#34;Optimize Resume&#34; to get improvement suggestions.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function optimizeResume() {
var text = document.getElementById(&#39;resume-opt-input&#39;).value;
var output = document.getElementById(&#39;resume-opt-output&#39;);
if (!text.trim()) { output.textContent = &#39;Please paste your resume text.&#39;; return; }
var wordCount = text.split(/\s+/).length;
var hasEmail = /[\w.-]+@[\w.-]+\.\w+/.test(text);
var hasPhone = /[\d\-\(\)\s+]{7,}/.test(text);
output.textContent = &#39;Resume Optimizer (Demo)\n\n&#39;;
output.textContent += &#39;Word count: &#39; + wordCount + &#39;\n&#39;;
output.textContent += &#39;Email found: &#39; + (hasEmail ? &#39;Yes&#39; : &#39;No - add your email&#39;) + &#39;\n&#39;;
output.textContent += &#39;Phone found: &#39; + (hasPhone ? &#39;Yes&#39; : &#39;No - add your phone&#39;) + &#39;\n\n&#39;;
output.textContent += &#39;This is a demo preview. The full optimizer will provide:\n&#39;;
output.textContent += &#39;- Keyword density analysis\n&#39;;
output.textContent += &#39;- Action verb suggestions\n&#39;;
output.textContent += &#39;- Formatting improvements\n&#39;;
output.textContent += &#39;- ATS compatibility score\n&#39;;
output.textContent += &#39;- Section completeness check\n\n&#39;;
output.textContent += &#39;Full optimization requires the backend AI service.&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Resume Optimizer analyzes your resume and provides actionable suggestions to improve its content, formatting, and keyword optimization for better ATS scores and recruiter appeal.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Allow all crawlers (basic)&lt;/label&gt;
&lt;div class=&#34;form-check&#34;&gt;
&lt;input class=&#34;form-check-input&#34; type=&#34;radio&#34; name=&#34;robots-mode&#34; id=&#34;mode-allow&#34; value=&#34;allow&#34; checked onchange=&#34;toggleRobotsMode()&#34;&gt;
&lt;label class=&#34;form-check-label&#34; for=&#34;mode-allow&#34;&gt;Allow all (public site)&lt;/label&gt;
&lt;/div&gt;
&lt;div class=&#34;form-check&#34;&gt;
&lt;input class=&#34;form-check-input&#34; type=&#34;radio&#34; name=&#34;robots-mode&#34; id=&#34;mode-block&#34; value=&#34;block&#34; onchange=&#34;toggleRobotsMode()&#34;&gt;
&lt;label class=&#34;form-check-label&#34; for=&#34;mode-block&#34;&gt;Block specific paths&lt;/label&gt;
&lt;/div&gt;
&lt;div class=&#34;form-check&#34;&gt;
&lt;input class=&#34;form-check-input&#34; type=&#34;radio&#34; name=&#34;robots-mode&#34; id=&#34;mode-custom&#34; value=&#34;custom&#34; onchange=&#34;toggleRobotsMode()&#34;&gt;
&lt;label class=&#34;form-check-label&#34; for=&#34;mode-custom&#34;&gt;Custom&lt;/label&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div id=&#34;robots-block-paths&#34; class=&#34;mb-3&#34; style=&#34;display:none;&#34;&gt;
&lt;label class=&#34;form-label&#34;&gt;Paths to block (one per line)&lt;/label&gt;
&lt;textarea id=&#34;robots-paths&#34; rows=&#34;4&#34; placeholder=&#34;/admin/
/private/
/temp/&#34;&gt;&lt;/textarea&gt;
&lt;/div&gt;
&lt;div id=&#34;robots-custom-area&#34; class=&#34;mb-3&#34; style=&#34;display:none;&#34;&gt;
&lt;label class=&#34;form-label&#34;&gt;Custom robots.txt content&lt;/label&gt;
&lt;textarea id=&#34;robots-custom&#34; rows=&#34;6&#34; placeholder=&#34;User-agent: *&amp;#10;Disallow: /&#34;&gt;&lt;/textarea&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label&#34;&gt;Sitemap URL (optional)&lt;/label&gt;
&lt;input type=&#34;text&#34; id=&#34;robots-sitemap&#34; placeholder=&#34;https://example.com/sitemap.xml&#34;&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;generateRobots()&#34;&gt;Generate&lt;/button&gt;
&lt;div class=&#34;mt-3 position-relative&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;robots.txt&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;robots-output&#34;&gt;Click &#34;Generate&#34; to create your robots.txt.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function toggleRobotsMode() {
var mode = document.querySelector(&#39;input[name=&#34;robots-mode&#34;]:checked&#39;).value;
document.getElementById(&#39;robots-block-paths&#39;).style.display = mode === &#39;block&#39; ? &#39;block&#39; : &#39;none&#39;;
document.getElementById(&#39;robots-custom-area&#39;).style.display = mode === &#39;custom&#39; ? &#39;block&#39; : &#39;none&#39;;
}
function generateRobots() {
var mode = document.querySelector(&#39;input[name=&#34;robots-mode&#34;]:checked&#39;).value;
var sitemap = document.getElementById(&#39;robots-sitemap&#39;).value.trim();
var output = document.getElementById(&#39;robots-output&#39;);
var text = &#39;&#39;;
if (mode === &#39;allow&#39;) {
text = &#39;User-agent: *\nAllow: /&#39;;
} else if (mode === &#39;block&#39;) {
var paths = document.getElementById(&#39;robots-paths&#39;).value.split(&#39;\n&#39;).filter(function(p) { return p.trim(); });
text = &#39;User-agent: *\n&#39; + paths.map(function(p) { return &#39;Disallow: &#39; + p.trim(); }).join(&#39;\n&#39;);
} else {
text = document.getElementById(&#39;robots-custom&#39;).value;
}
if (sitemap) text += &#39;\n\nSitemap: &#39; + sitemap;
output.textContent = text;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Robots.txt Generator helps you create a valid robots.txt file for your website. Control which search engine crawlers can access which parts of your site.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Schema type&lt;/label&gt;
&lt;select id=&#34;schema-type&#34; class=&#34;form-select&#34; onchange=&#34;toggleSchemaFields()&#34;&gt;
&lt;option value=&#34;Article&#34;&gt;Article&lt;/option&gt;
&lt;option value=&#34;FAQPage&#34;&gt;FAQ&lt;/option&gt;
&lt;option value=&#34;Product&#34;&gt;Product&lt;/option&gt;
&lt;option value=&#34;Organization&#34;&gt;Organization&lt;/option&gt;
&lt;option value=&#34;LocalBusiness&#34;&gt;Local Business&lt;/option&gt;
&lt;option value=&#34;Person&#34;&gt;Person&lt;/option&gt;
&lt;/select&gt;
&lt;/div&gt;
&lt;div id=&#34;schema-fields&#34;&gt;&lt;/div&gt;
&lt;button class=&#34;btn btn-primary mt-3&#34; onclick=&#34;generateSchema()&#34;&gt;Generate Schema&lt;/button&gt;
&lt;div class=&#34;mt-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;JSON-LD Schema&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;schema-output&#34;&gt;Select a schema type and fill in the fields.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
var schemaFields = {
Article: [{ id: &#39;schema-headline&#39;, label: &#39;Headline&#39;, type: &#39;text&#39; }, { id: &#39;schema-author&#39;, label: &#39;Author&#39;, type: &#39;text&#39; }, { id: &#39;schema-date&#39;, label: &#39;Date published&#39;, type: &#39;date&#39; }],
FAQPage: [{ id: &#39;schema-questions&#39;, label: &#39;Questions (one per line, format: Q: ... A: ...)&#39;, type: &#39;textarea&#39; }],
Product: [{ id: &#39;schema-product-name&#39;, label: &#39;Product name&#39;, type: &#39;text&#39; }, { id: &#39;schema-product-price&#39;, label: &#39;Price&#39;, type: &#39;text&#39; }, { id: &#39;schema-product-currency&#39;, label: &#39;Currency&#39;, type: &#39;text&#39;, val: &#39;USD&#39; }],
Organization: [{ id: &#39;schema-org-name&#39;, label: &#39;Organization name&#39;, type: &#39;text&#39; }, { id: &#39;schema-org-url&#39;, label: &#39;URL&#39;, type: &#39;url&#39; }],
LocalBusiness: [{ id: &#39;schema-biz-name&#39;, label: &#39;Business name&#39;, type: &#39;text&#39; }, { id: &#39;schema-biz-addr&#39;, label: &#39;Address&#39;, type: &#39;text&#39; }, { id: &#39;schema-biz-phone&#39;, label: &#39;Phone&#39;, type: &#39;text&#39; }],
Person: [{ id: &#39;schema-person-name&#39;, label: &#39;Name&#39;, type: &#39;text&#39; }, { id: &#39;schema-person-job&#39;, label: &#39;Job title&#39;, type: &#39;text&#39; }]
};
function toggleSchemaFields() {
var type = document.getElementById(&#39;schema-type&#39;).value;
var container = document.getElementById(&#39;schema-fields&#39;);
container.innerHTML = &#39;&#39;;
(schemaFields[type] || []).forEach(function(f) {
var div = document.createElement(&#39;div&#39;);
div.className = &#39;mb-2&#39;;
var label = document.createElement(&#39;label&#39;);
label.className = &#39;form-label fw-semibold&#39;;
label.textContent = f.label;
div.appendChild(label);
if (f.type === &#39;textarea&#39;) {
var ta = document.createElement(&#39;textarea&#39;);
ta.id = f.id;
ta.className = &#39;form-control&#39;;
ta.rows = 4;
div.appendChild(ta);
} else {
var input = document.createElement(&#39;input&#39;);
input.type = f.type;
input.id = f.id;
input.className = &#39;form-control&#39;;
if (f.val) input.value = f.val;
div.appendChild(input);
}
container.appendChild(div);
});
}
function generateSchema() {
var type = document.getElementById(&#39;schema-type&#39;).value;
var output = document.getElementById(&#39;schema-output&#39;);
var schema = { &#39;@context&#39;: &#39;https://schema.org&#39;, &#39;@type&#39;: type };
switch (type) {
case &#39;Article&#39;:
schema.headline = document.getElementById(&#39;schema-headline&#39;).value || &#39;Article Title&#39;;
schema.author = { &#39;@type&#39;: &#39;Person&#39;, name: document.getElementById(&#39;schema-author&#39;).value || &#39;Author&#39; };
schema.datePublished = document.getElementById(&#39;schema-date&#39;).value || new Date().toISOString().split(&#39;T&#39;)[0];
break;
case &#39;FAQPage&#39;:
var text = document.getElementById(&#39;schema-questions&#39;).value;
if (text.trim()) {
schema.mainEntity = text.split(&#39;\n&#39;).filter(function(l) { return l.trim(); }).map(function(l) {
var parts = l.split(/[QA]:\s*/).filter(Boolean);
return { &#39;@type&#39;: &#39;Question&#39;, name: parts[0] || l, acceptedAnswer: { &#39;@type&#39;: &#39;Answer&#39;, text: parts[1] || &#39;&#39; } };
});
}
break;
case &#39;Product&#39;:
schema.name = document.getElementById(&#39;schema-product-name&#39;).value || &#39;Product&#39;;
schema.offers = { &#39;@type&#39;: &#39;Offer&#39;, price: document.getElementById(&#39;schema-product-price&#39;).value || &#39;0&#39;, priceCurrency: document.getElementById(&#39;schema-product-currency&#39;).value || &#39;USD&#39; };
break;
case &#39;Organization&#39;:
schema.name = document.getElementById(&#39;schema-org-name&#39;).value || &#39;Organization&#39;;
schema.url = document.getElementById(&#39;schema-org-url&#39;).value || &#39;https://example.com&#39;;
break;
case &#39;LocalBusiness&#39;:
schema.name = document.getElementById(&#39;schema-biz-name&#39;).value || &#39;Business&#39;;
schema.address = { &#39;@type&#39;: &#39;PostalAddress&#39;, streetAddress: document.getElementById(&#39;schema-biz-addr&#39;).value || &#39;&#39; };
schema.telephone = document.getElementById(&#39;schema-biz-phone&#39;).value || &#39;&#39;;
break;
case &#39;Person&#39;:
schema.name = document.getElementById(&#39;schema-person-name&#39;).value || &#39;Person&#39;;
if (document.getElementById(&#39;schema-person-job&#39;).value) schema.jobTitle = document.getElementById(&#39;schema-person-job&#39;).value;
break;
}
output.textContent = JSON.stringify(schema, null, 2);
}
toggleSchemaFields();
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Schema Generator creates structured data markup (JSON-LD) for your website. Get rich snippets in search results with Article, Product, FAQ, Local Business, and more schema types.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Your website URL&lt;/label&gt;
&lt;input type=&#34;url&#34; id=&#34;sitemap-url&#34; class=&#34;form-control&#34; placeholder=&#34;https://example.com&#34;&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Change frequency&lt;/label&gt;
&lt;select id=&#34;sitemap-freq&#34; class=&#34;form-select&#34;&gt;
&lt;option value=&#34;daily&#34;&gt;Daily&lt;/option&gt;
&lt;option value=&#34;weekly&#34; selected&gt;Weekly&lt;/option&gt;
&lt;option value=&#34;monthly&#34;&gt;Monthly&lt;/option&gt;
&lt;option value=&#34;yearly&#34;&gt;Yearly&lt;/option&gt;
&lt;/select&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;generateSitemap()&#34;&gt;Generate Sitemap&lt;/button&gt;
&lt;div class=&#34;mt-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;XML Sitemap&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;sitemap-output&#34;&gt;Enter your URL and click &#34;Generate Sitemap&#34;.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function generateSitemap() {
var url = document.getElementById(&#39;sitemap-url&#39;).value.trim();
var freq = document.getElementById(&#39;sitemap-freq&#39;).value;
var output = document.getElementById(&#39;sitemap-output&#39;);
if (!url) { output.textContent = &#39;Please enter your website URL.&#39;; return; }
var today = new Date().toISOString().split(&#39;T&#39;)[0];
var sitemap = &#39;&lt;?xml version=&#34;1.0&#34; encoding=&#34;UTF-8&#34;?&gt;\n&#39;;
sitemap += &#39;&lt;urlset xmlns=&#34;http://www.sitemaps.org/schemas/sitemap/0.9&#34;&gt;\n&#39;;
sitemap += &#39; &lt;url&gt;\n&#39;;
sitemap += &#39; &lt;loc&gt;&#39; + url.replace(/\/$/, &#39;&#39;) + &#39;/&lt;/loc&gt;\n&#39;;
sitemap += &#39; &lt;lastmod&gt;&#39; + today + &#39;&lt;/lastmod&gt;\n&#39;;
sitemap += &#39; &lt;changefreq&gt;&#39; + freq + &#39;&lt;/changefreq&gt;\n&#39;;
sitemap += &#39; &lt;priority&gt;1.0&lt;/priority&gt;\n&#39;;
sitemap += &#39; &lt;/url&gt;\n&#39;;
var pages = [&#39;about&#39;, &#39;tools&#39;, &#39;contact&#39;, &#39;blog&#39;];
var priority = 0.8;
pages.forEach(function(p) {
sitemap += &#39; &lt;url&gt;\n&#39;;
sitemap += &#39; &lt;loc&gt;&#39; + url.replace(/\/$/, &#39;&#39;) + &#39;/&#39; + p + &#39;/&lt;/loc&gt;\n&#39;;
sitemap += &#39; &lt;lastmod&gt;&#39; + today + &#39;&lt;/lastmod&gt;\n&#39;;
sitemap += &#39; &lt;changefreq&gt;&#39; + freq + &#39;&lt;/changefreq&gt;\n&#39;;
sitemap += &#39; &lt;priority&gt;&#39; + priority.toFixed(1) + &#39;&lt;/priority&gt;\n&#39;;
sitemap += &#39; &lt;/url&gt;\n&#39;;
priority -= 0.1;
});
sitemap += &#39;&lt;/urlset&gt;&#39;;
output.textContent = sitemap;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Sitemap Generator creates XML sitemaps for your website. Help search engines discover and index all your pages with a properly formatted sitemap.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Upload PDF to split&lt;/label&gt;
&lt;input type=&#34;file&#34; id=&#34;pdf-split-input&#34; accept=&#34;.pdf&#34; class=&#34;form-control mb-2&#34;&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Split mode&lt;/label&gt;
&lt;select id=&#34;pdf-split-mode&#34; class=&#34;form-select&#34;&gt;
&lt;option value=&#34;range&#34;&gt;Extract page range&lt;/option&gt;
&lt;option value=&#34;all&#34;&gt;Split every page&lt;/option&gt;
&lt;/select&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34; id=&#34;pdf-split-range&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Page range (e.g. 1-5, 8, 11-15)&lt;/label&gt;
&lt;input type=&#34;text&#34; id=&#34;pdf-split-pages&#34; class=&#34;form-control&#34; placeholder=&#34;1-5, 8, 11-15&#34;&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;splitPDF()&#34;&gt;Split PDF&lt;/button&gt;
&lt;div class=&#34;mt-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Result&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;pdf-split-output&#34;&gt;Upload a PDF to split pages. Note: This requires server-side processing.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
document.getElementById(&#39;pdf-split-mode&#39;).addEventListener(&#39;change&#39;, function() {
document.getElementById(&#39;pdf-split-range&#39;).style.display = this.value === &#39;range&#39; ? &#39;block&#39; : &#39;none&#39;;
});
function splitPDF() {
var file = document.getElementById(&#39;pdf-split-input&#39;).files[0];
var output = document.getElementById(&#39;pdf-split-output&#39;);
if (!file) { output.textContent = &#39;Please upload a PDF file.&#39;; return; }
output.textContent = &#39;PDF Splitter (Demo)\n\n&#39;;
output.textContent += &#39;File: &#39; + file.name + &#39; (&#39; + (file.size / 1024).toFixed(1) + &#39; KB)\n\n&#39;;
output.textContent += &#39;This tool requires server-side PDF processing.\n&#39;;
output.textContent += &#39;Full PDF splitting will be available when the backend is running.\n\n&#39;;
output.textContent += &#39;Planned features:\n&#39;;
output.textContent += &#39;- Extract specific page ranges\n&#39;;
output.textContent += &#39;- Split every page into separate files\n&#39;;
output.textContent += &#39;- Merge extracted pages into a new PDF&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Split PDF lets you extract specific pages from a PDF file or split a PDF into multiple smaller documents. Perfect for separating chapters, sections, or selected pages.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Enter text to summarize&lt;/label&gt;
&lt;textarea id=&#34;summary-input&#34; rows=&#34;10&#34; placeholder=&#34;Paste article, document, or long text here...&#34;&gt;&lt;/textarea&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Summary length&lt;/label&gt;
&lt;select id=&#34;summary-length&#34; class=&#34;form-select&#34;&gt;
&lt;option value=&#34;short&#34;&gt;Short (1-2 sentences)&lt;/option&gt;
&lt;option value=&#34;medium&#34; selected&gt;Medium (1 paragraph)&lt;/option&gt;
&lt;option value=&#34;long&#34;&gt;Long (2-3 paragraphs)&lt;/option&gt;
&lt;/select&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;summarizeText()&#34;&gt;Summarize&lt;/button&gt;
&lt;div class=&#34;mt-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Summary&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;summary-output&#34;&gt;Click &#34;Summarize&#34; to condense your text.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function summarizeText() {
var text = document.getElementById(&#39;summary-input&#39;).value;
var length = document.getElementById(&#39;summary-length&#39;).value;
var output = document.getElementById(&#39;summary-output&#39;);
if (!text.trim()) { output.textContent = &#39;Please enter some text.&#39;; return; }
var wordCount = text.split(/\s+/).length;
output.textContent = &#39;Text Summarizer (Demo)\n\n&#39;;
output.textContent += &#39;Original word count: &#39; + wordCount + &#39;\n&#39;;
output.textContent += &#39;Summary length: &#39; + length + &#39;\n\n&#39;;
output.textContent += &#39;This is a demo preview. The full AI summarizer will produce:\n&#39;;
output.textContent += &#39;- Concise summary of key points\n&#39;;
output.textContent += &#39;- Main arguments and conclusions\n&#39;;
output.textContent += &#39;- Important data and statistics\n\n&#39;;
output.textContent += &#39;Full summarization requires the backend AI service.&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;Text Summarizer condenses long articles, documents, and any text into clear, concise summaries. Save time by getting the key points without reading the entire content.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;UUID version&lt;/label&gt;
&lt;select id=&#34;uuid-version&#34; class=&#34;form-select&#34;&gt;
&lt;option value=&#34;v4&#34;&gt;UUID v4 (Random)&lt;/option&gt;
&lt;option value=&#34;v7&#34;&gt;UUID v7 (Time-ordered)&lt;/option&gt;
&lt;/select&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Format&lt;/label&gt;
&lt;div class=&#34;d-flex gap-3&#34;&gt;
&lt;div class=&#34;form-check&#34;&gt;&lt;input type=&#34;radio&#34; name=&#34;uuid-format&#34; id=&#34;uuid-format-default&#34; class=&#34;form-check-input&#34; checked value=&#34;default&#34;&gt;&lt;label class=&#34;form-check-label&#34; for=&#34;uuid-format-default&#34;&gt;With hyphens&lt;/label&gt;&lt;/div&gt;
&lt;div class=&#34;form-check&#34;&gt;&lt;input type=&#34;radio&#34; name=&#34;uuid-format&#34; id=&#34;uuid-format-nohyph&#34; class=&#34;form-check-input&#34; value=&#34;nohyph&#34;&gt;&lt;label class=&#34;form-check-label&#34; for=&#34;uuid-format-nohyph&#34;&gt;No hyphens&lt;/label&gt;&lt;/div&gt;
&lt;div class=&#34;form-check&#34;&gt;&lt;input type=&#34;radio&#34; name=&#34;uuid-format&#34; id=&#34;uuid-format-upper&#34; class=&#34;form-check-input&#34; value=&#34;upper&#34;&gt;&lt;label class=&#34;form-check-label&#34; for=&#34;uuid-format-upper&#34;&gt;UPPERCASE&lt;/label&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Quantity&lt;/label&gt;
&lt;input type=&#34;number&#34; id=&#34;uuid-count&#34; class=&#34;form-control&#34; value=&#34;1&#34; min=&#34;1&#34; max=&#34;100&#34; style=&#34;max-width:100px&#34;&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary mb-3&#34; onclick=&#34;generateUUIDs()&#34;&gt;Generate UUIDs&lt;/button&gt;
&lt;div&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Generated UUIDs&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;uuid-output&#34;&gt;Click &#34;Generate UUIDs&#34; to create unique identifiers.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function generateUUIDs() {
var ver = document.getElementById(&#39;uuid-version&#39;).value;
var count = parseInt(document.getElementById(&#39;uuid-count&#39;).value) || 1;
var formatEl = document.querySelector(&#39;input[name=&#34;uuid-format&#34;]:checked&#39;);
var format = formatEl ? formatEl.value : &#39;default&#39;;
var output = document.getElementById(&#39;uuid-output&#39;);
function uuidV4() {
var hex = &#39;0123456789abcdef&#39;;
var s = &#39;&#39;;
for (var i = 0; i &lt; 36; i++) {
if (i === 8 || i === 13 || i === 18 || i === 23) { s += &#39;-&#39;; continue; }
if (i === 14) { s += &#39;4&#39;; continue; }
if (i === 19) { s += hex.charAt(Math.floor(Math.random() * 4) + 8); continue; }
s += hex.charAt(Math.floor(Math.random() * 16));
}
return s;
}
function uuidV7() {
var ts = Date.now().toString(16).padStart(12, &#39;0&#39;);
var hex = &#39;0123456789abcdef&#39;;
var s = ts;
for (var i = 0; i &lt; 24; i++) {
if (i === 8 || i === 13 || i === 18 || i === 23) continue;
s += hex.charAt(Math.floor(Math.random() * 16));
}
return s.substr(0, 8) + &#39;-&#39; + s.substr(8, 4) + &#39;-7&#39; + s.substr(12, 3) + &#39;-&#39; + hex.charAt(Math.floor(Math.random() * 4) + 8) + s.substr(15, 3) + &#39;-&#39; + s.substr(18, 12);
}
var result = &#39;&#39;;
for (var i = 0; i &lt; count; i++) {
var uuid = ver === &#39;v4&#39; ? uuidV4() : uuidV7();
if (format === &#39;nohyph&#39;) uuid = uuid.replace(/-/g, &#39;&#39;);
if (format === &#39;upper&#39;) uuid = uuid.toUpperCase();
result += uuid + &#39;\n&#39;;
}
output.textContent = result.trim();
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;UUID Generator creates universally unique identifiers (UUIDs) in multiple versions. Generate one or many UUIDs instantly for use in databases, APIs, and distributed systems.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Upload image to convert to WebP&lt;/label&gt;
&lt;input type=&#34;file&#34; id=&#34;webp-input&#34; accept=&#34;image/*&#34; class=&#34;form-control mb-2&#34;&gt;
&lt;/div&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Quality&lt;/label&gt;
&lt;input type=&#34;range&#34; id=&#34;webp-quality&#34; class=&#34;form-range&#34; min=&#34;10&#34; max=&#34;100&#34; value=&#34;80&#34;&gt;
&lt;span id=&#34;webp-quality-label&#34;&gt;80%&lt;/span&gt;
&lt;/div&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;convertToWebP()&#34;&gt;Convert to WebP&lt;/button&gt;
&lt;div class=&#34;mt-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Preview&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;webp-output&#34;&gt;Upload an image and click &#34;Convert to WebP&#34;.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
document.getElementById(&#39;webp-quality&#39;).addEventListener(&#39;input&#39;, function() {
document.getElementById(&#39;webp-quality-label&#39;).textContent = this.value + &#39;%&#39;;
});
function convertToWebP() {
var file = document.getElementById(&#39;webp-input&#39;).files[0];
var quality = parseInt(document.getElementById(&#39;webp-quality&#39;).value) / 100;
var output = document.getElementById(&#39;webp-output&#39;);
if (!file) { output.textContent = &#39;Please upload an image first.&#39;; return; }
var img = new Image();
img.onload = function() {
var canvas = document.createElement(&#39;canvas&#39;);
canvas.width = img.width;
canvas.height = img.height;
var ctx = canvas.getContext(&#39;2d&#39;);
ctx.drawImage(img, 0, 0);
var webpData = canvas.toDataURL(&#39;image/webp&#39;, quality);
var link = document.createElement(&#39;a&#39;);
link.download = file.name.replace(/\.[^.]+$/, &#39;.webp&#39;);
link.href = webpData;
link.click();
var originalSize = file.size;
var webpSize = Math.round(webpData.length * 0.75);
var savings = Math.round((1 - webpSize / originalSize) * 100);
output.textContent = &#39;Converted to WebP. Estimated savings: &#39; + savings + &#39;% (&#39; + formatBytes(originalSize) + &#39; → &#39; + formatBytes(webpSize) + &#39;)&#39;;
};
img.src = URL.createObjectURL(file);
}
function formatBytes(b) {
if (b &lt; 1024) return b + &#39; B&#39;;
if (b &lt; 1048576) return (b / 1024).toFixed(1) + &#39; KB&#39;;
return (b / 1048576).toFixed(1) + &#39; MB&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;WebP Converter converts your images to WebP format — Google&amp;rsquo;s modern image format that provides superior compression. Reduce image sizes by 25-35% without noticeable quality loss.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Enter XML&lt;/label&gt;
&lt;textarea id=&#34;xml-input&#34; rows=&#34;8&#34; placeholder=&#34;Paste your XML here...&#34;&gt;&lt;/textarea&gt;
&lt;/div&gt;
&lt;div class=&#34;d-flex gap-2 mb-3 flex-wrap&#34;&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;formatXML()&#34;&gt;Format&lt;/button&gt;
&lt;button class=&#34;btn btn-outline-secondary&#34; onclick=&#34;minifyXML()&#34;&gt;Minify&lt;/button&gt;
&lt;button class=&#34;btn btn-outline-secondary&#34; onclick=&#34;clearXML()&#34;&gt;Clear&lt;/button&gt;
&lt;/div&gt;
&lt;div&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Output&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;xml-output&#34;&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function formatXML() {
var input = document.getElementById(&#39;xml-input&#39;);
var output = document.getElementById(&#39;xml-output&#39;);
var xml = input.value;
if (!xml.trim()) { output.textContent = &#39;Please enter XML.&#39;; return; }
try {
var parser = new DOMParser();
var doc = parser.parseFromString(xml, &#39;text/xml&#39;);
var serializer = new XMLSerializer();
var formatted = serializer.serializeToString(doc);
formatted = formatted.replace(/&gt;&lt;/g, &#39;&gt;\n&lt;&#39;);
var indent = 0;
formatted = formatted.split(&#39;\n&#39;).map(function(line) {
if (line.match(/&lt;\/\w/)) indent--;
var result = &#39; &#39;.repeat(Math.max(0, indent)) + line;
if (line.match(/&lt;[^/]\w[^&gt;]*[^/]&gt;/)) indent++;
return result;
}).join(&#39;\n&#39;);
output.textContent = formatted;
} catch(e) { output.textContent = &#39;Error: &#39; + e.message; }
}
function minifyXML() {
var input = document.getElementById(&#39;xml-input&#39;);
var output = document.getElementById(&#39;xml-output&#39;);
try {
var parser = new DOMParser();
var doc = parser.parseFromString(input.value, &#39;text/xml&#39;);
var serializer = new XMLSerializer();
var minified = serializer.serializeToString(doc);
output.textContent = minified.replace(/\s{2,}/g, &#39;&#39;).replace(/&gt;\s+&lt;/g, &#39;&gt;&lt;&#39;);
} catch(e) { output.textContent = &#39;Error: &#39; + e.message; }
}
function clearXML() {
document.getElementById(&#39;xml-input&#39;).value = &#39;&#39;;
document.getElementById(&#39;xml-output&#39;).textContent = &#39;&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;XML Formatter beautifies, minifies, and validates XML data. Perfect for working with XML APIs, config files, and data exchange formats.&lt;/p&gt;

&lt;div class=&#34;tool-wrapper&#34;&gt;
&lt;div class=&#34;mb-3&#34;&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Enter YAML&lt;/label&gt;
&lt;textarea id=&#34;yaml-input&#34; rows=&#34;8&#34; placeholder=&#34;Paste your YAML here...&#34;&gt;&lt;/textarea&gt;
&lt;/div&gt;
&lt;div class=&#34;d-flex gap-2 mb-3 flex-wrap&#34;&gt;
&lt;button class=&#34;btn btn-primary&#34; onclick=&#34;formatYAML()&#34;&gt;Format&lt;/button&gt;
&lt;button class=&#34;btn btn-outline-secondary&#34; onclick=&#34;minifyYAML()&#34;&gt;Minify&lt;/button&gt;
&lt;button class=&#34;btn btn-outline-secondary&#34; onclick=&#34;yamlToJSON()&#34;&gt;To JSON&lt;/button&gt;
&lt;button class=&#34;btn btn-outline-secondary&#34; onclick=&#34;clearYAML()&#34;&gt;Clear&lt;/button&gt;
&lt;/div&gt;
&lt;div&gt;
&lt;label class=&#34;form-label fw-semibold&#34;&gt;Output&lt;/label&gt;
&lt;div class=&#34;tool-output&#34; id=&#34;yaml-output&#34;&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;script&gt;
function formatYAML() {
var input = document.getElementById(&#39;yaml-input&#39;);
var output = document.getElementById(&#39;yaml-output&#39;);
var yaml = input.value;
if (!yaml.trim()) { output.textContent = &#39;Please enter YAML.&#39;; return; }
var lines = yaml.split(&#39;\n&#39;);
var formatted = lines.map(function(line) {
var trimmed = line.replace(/\s+$/, &#39;&#39;);
var indent = line.match(/^(\s*)/)[1];
var content = trimmed.trim();
if (content.startsWith(&#39;#&#39;)) return trimmed;
return indent + content;
}).filter(function(l) { return l.trim() !== &#39;&#39;; }).join(&#39;\n&#39;);
output.textContent = formatted;
}
function minifyYAML() {
var input = document.getElementById(&#39;yaml-input&#39;);
var output = document.getElementById(&#39;yaml-output&#39;);
output.textContent = input.value.replace(/^\s*#.*$/gm, &#39;&#39;).replace(/^\s*[\n\r]/gm, &#39;&#39;).trim();
}
function yamlToJSON() {
var input = document.getElementById(&#39;yaml-input&#39;);
var output = document.getElementById(&#39;yaml-output&#39;);
output.textContent = &#39;YAML to JSON conversion requires js-yaml library.\n\nFor now, this is a placeholder. Full functionality coming soon.&#39;;
}
function clearYAML() {
document.getElementById(&#39;yaml-input&#39;).value = &#39;&#39;;
document.getElementById(&#39;yaml-output&#39;).textContent = &#39;&#39;;
}
&lt;/script&gt;
&lt;h2 id=&#34;introduction&#34;&gt;Introduction&lt;/h2&gt;
&lt;p&gt;YAML Formatter helps you beautify, validate, and convert YAML data. Essential for working with Docker Compose, Kubernetes configs, CI/CD pipelines, and more.&lt;/p&gt;
